# ── AUTO INSTALL DEPENDENCIES ────────────────────────────────────────────────
def _auto_install():
    import subprocess, sys
    REQUIRED = ["psutil", "pywin32", "wmi"]
    missing  = []
    for pkg in REQUIRED:
        try:
            __import__(pkg if pkg != "pywin32" else "win32api")
        except ImportError:
            missing.append(pkg)
    if missing:
        print(f"[*] Installing: {', '.join(missing)} ...")
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install", "--quiet"] + missing,
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
            )
            print(f"[+] Install selesai: {', '.join(missing)}")
        except Exception as e:
            print(f"[!] Gagal install otomatis: {e}")
            print(f"[!] Jalankan manual: pip install {' '.join(missing)}")
            sys.exit(1)

_auto_install()
