findings_summary = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "INFO": 0}

def add_finding(findings, severity, title, detail, raw=None):
    findings_summary[severity] = findings_summary.get(severity, 0) + 1
    findings.append({
        "severity": severity,
        "title": title,
        "detail": detail,
        "raw": raw or ""
    })

# ── MODULE 1: PROCESSES ──────────────────────────────────────────────────────
def check_processes():
    findings = []
    process_list = []
    try:
        for proc in psutil.process_iter(['pid', 'name', 'exe', 'username', 'cmdline', 'create_time']):
            try:
                info = proc.info
                exe = info.get('exe') or ''
                name = (info.get('name') or '').lower()
                cmdline = ' '.join(info.get('cmdline') or [])
                created = datetime.datetime.fromtimestamp(info['create_time']).strftime('%Y-%m-%d %H:%M:%S') if info.get('create_time') else '-'

                flags = []
                if name in WINDOWS_LEGITIMATE_PROCESSES:
                    continue
                exe_lower = exe.lower()
                is_legit_path = any(exe_lower.startswith(lp) for lp in WINDOWS_LEGITIMATE_PATHS)
                if not is_legit_path:
                    for sp in SUSPICIOUS_PATHS:
                        if sp and exe_lower.startswith(sp.lower()):
                            flags.append(f"Berjalan dari path mencurigakan: {sp}")
                for bad in SUSPICIOUS_PROCESS_NAMES:
                    if bad in name:
                        flags.append(f"Nama proses mencurigakan: {name}")
                if exe and not is_legit_path and exe.count('.') > 1 and exe.lower().split('.')[-2] in ['exe','dll','bat','ps1']:
                    flags.append("Ekstensi ganda terdeteksi")

                severity = None
                if any("Nama proses" in f for f in flags):
                    severity = "CRITICAL"
                elif any("Ekstensi ganda" in f for f in flags):
                    severity = "HIGH"
                elif flags:
                    severity = "MEDIUM"

                entry = {
                    "pid": info['pid'],
                    "name": info['name'],
                    "exe": exe or '-',
                    "user": info.get('username') or '-',
                    "cmdline": cmdline[:120] or '-',
                    "created": created,
                    "flags": flags,
                    "severity": severity
                }
                process_list.append(entry)

                if severity:
                    add_finding(findings, severity,
                        f"Proses mencurigakan: {info['name']} (PID {info['pid']})",
                        f"Path: {exe or '-'} | User: {info.get('username') or '-'} | CMD: {cmdline[:80] or '-'} | {' | '.join(flags)}",
                        raw=json.dumps(entry, ensure_ascii=False))
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
    except Exception as e:
        add_finding(findings, "INFO", "Process check error", str(e))
    return findings, process_list

# ── MODULE 2: NETWORK ────────────────────────────────────────────────────────
def check_network():
    findings = []
    conn_list = []
    try:
        for conn in psutil.net_connections(kind='all'):
            try:
                laddr = f"{conn.laddr.ip}:{conn.laddr.port}" if conn.laddr else '-'
                raddr = f"{conn.raddr.ip}:{conn.raddr.port}" if conn.raddr else '-'
                rport = conn.raddr.port if conn.raddr else 0
                rip = conn.raddr.ip if conn.raddr else ''

                flags = []
                if rport in KNOWN_BAD_PORTS:
                    flags.append(f"Port mencurigakan: {rport}")
                if rip and rip.startswith(('10.','172.16.','192.168.')) and rport in KNOWN_BAD_PORTS:
                    flags.append("Koneksi C2 internal yang mencurigakan")

                try:
                    proc_name = psutil.Process(conn.pid).name() if conn.pid else '-'
                except:
                    proc_name = '-'

                severity = "HIGH" if flags else None
                entry = {
                    "laddr": laddr, "raddr": raddr,
                    "status": conn.status, "pid": conn.pid,
                    "proc": proc_name, "flags": flags, "severity": severity
                }
                conn_list.append(entry)
                if severity:
                    add_finding(findings, severity,
                        f"Koneksi jaringan mencurigakan: {raddr}",
                        f"Local: {laddr} → Remote: {raddr} | Process: {proc_name} (PID {conn.pid}) | Status: {conn.status} | {' | '.join(flags)}",
                        raw=json.dumps(entry, ensure_ascii=False))
            except Exception:
                continue
    except Exception as e:
        add_finding(findings, "INFO", "Network check error", str(e))
    return findings, conn_list

# ── MODULE 3: PERSISTENCE ────────────────────────────────────────────────────
def check_persistence():
    findings = []
    persistence_list = []
    reg_run_keys = [
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"),
        (winreg.HKEY_CURRENT_USER,  r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_CURRENT_USER,  r"SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Run"),
    ]
    for hive, key_path in reg_run_keys:
        try:
            key = winreg.OpenKey(hive, key_path)
            i = 0
            while True:
                try:
                    name, val, _ = winreg.EnumValue(key, i)
                    flags = []
                    val_lower = val.lower()
                    for sp in SUSPICIOUS_PATHS:
                        if sp and sp.lower() in val_lower:
                            flags.append(f"Path mencurigakan: {sp}")
                    if any(ext in val_lower for ext in ['.ps1', '.vbs', '.bat', '.cmd', '.js']):
                        flags.append("Script execution via registry")
                    severity = "HIGH" if flags else "INFO"
                    entry = {"type": "Registry Run", "hive": str(hive), "key": key_path,
                             "name": name, "value": val, "flags": flags, "severity": severity}
                    persistence_list.append(entry)
                    if flags:
                        add_finding(findings, severity,
                            f"Registry persistence: {name}",
                            " | ".join(flags),
                            raw=json.dumps(entry, ensure_ascii=False))
                    i += 1
                except OSError:
                    break
            winreg.CloseKey(key)
        except Exception:
            continue

    try:
        import csv as _csv
        import io as _io
        result = subprocess.run(['schtasks', '/query', '/fo', 'CSV', '/v'],
                                capture_output=True, text=True, timeout=30)
        # Pakai csv.reader supaya koma di dalam field ter-handle
        reader = _csv.reader(_io.StringIO(result.stdout))
        rows = list(reader)
        if len(rows) > 1:
            header = rows[0]
            # Cari index kolom "Task To Run" (lokasinya bisa beda per locale/OS)
            try:
                cmd_idx = header.index("Task To Run")
            except ValueError:
                cmd_idx = 8  # fallback ke index default
            try:
                name_idx = header.index("TaskName")
            except ValueError:
                name_idx = 0
            for parts in rows[1:]:
                if len(parts) <= max(cmd_idx, name_idx):
                    continue
                task_name = parts[name_idx]
                task_cmd  = parts[cmd_idx]
                flags = []
                cmd_lower = task_cmd.lower()
                for sp in SUSPICIOUS_PATHS:
                    if sp and sp.lower() in cmd_lower:
                        flags.append("Task command di path mencurigakan")
                if any(ext in cmd_lower for ext in ['.ps1', '.vbs', '.bat']):
                    flags.append("Script execution via scheduled task")
                task_lower = task_name.lower()
                is_legit_task = any(lt in task_lower for lt in WINDOWS_LEGITIMATE_SCHTASKS)
                if flags and not is_legit_task:
                    entry = {"type": "Scheduled Task", "name": task_name,
                             "command": task_cmd, "flags": flags, "severity": "HIGH"}
                    persistence_list.append(entry)
                    add_finding(findings, "HIGH",
                        f"Scheduled task mencurigakan: {task_name}",
                        " | ".join(flags),
                        raw=json.dumps(entry, ensure_ascii=False))
    except Exception as e:
        add_finding(findings, "INFO", "Schtasks check error", str(e))

    # Whitelist nama vendor umum untuk startup .lnk — biasanya legit (installed by vendor)
    STARTUP_LNK_LEGIT_VENDORS = [
        # Office / Microsoft
        "microsoft", "onenote", "onedrive", "teams", "skype",
        # Adobe
        "adobe", "acrobat", "reader",
        # Google
        "google", "chrome",
        # Autodesk ecosystem (Chaos Group = legit 3D render plugin)
        "autodesk", "chaos", "ccbservice", "chaosunifiedlogin", "chaos license",
        "backburner", "vray", "corona",
        # Development tools
        "jetbrains", "visualstudio", "intellij",
        # Common vendor services / OEM
        "dell", "hp ", "lenovo", "asus", "acer", "msi ",
        "intel ", "amd ", "nvidia", "realtek",
        "discord", "slack", "spotify", "whatsapp", "telegram",
        # Security tools
        "defender", "firewall", "cylance", "crowdstrike",
    ]

    startup_dirs = [
        os.path.join(os.environ.get("APPDATA",""), r"Microsoft\Windows\Start Menu\Programs\Startup"),
        r"C:\ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp",
    ]
    for sd in startup_dirs:
        if os.path.isdir(sd):
            for f in os.listdir(sd):
                fp = os.path.join(sd, f)
                f_lower = f.lower()
                if f_lower in WINDOWS_LEGITIMATE_STARTUP:
                    continue
                # Check vendor whitelist — downgrade ke INFO kalau match
                is_vendor_legit = any(v in f_lower for v in STARTUP_LNK_LEGIT_VENDORS)
                severity = "INFO" if is_vendor_legit else "MEDIUM"
                entry = {"type": "Startup folder", "path": fp, "flags": [], "severity": severity,
                         "vendor_whitelist_match": is_vendor_legit}
                persistence_list.append(entry)
                add_finding(findings, severity,
                    f"Item di startup folder: {f}",
                    f"{fp} | {'(vendor whitelist OK)' if is_vendor_legit else 'periksa manual'}",
                    raw=json.dumps(entry, ensure_ascii=False))

    return findings, persistence_list

# ── MODULE 4: SUSPICIOUS FILES ───────────────────────────────────────────────
def check_suspicious_files():
    findings  = []
    file_list = []

    _raw_dirs = [
        os.environ.get("TEMP", ""),
        os.environ.get("TMP", ""),
        os.path.join(os.environ.get("LOCALAPPDATA",""), "Temp"),
    ]
    scan_dirs = list(dict.fromkeys(d for d in _raw_dirs if d))

    SKIP_FILE_DIRS = {
        r"c:\programdata\microsoft",
        r"c:\programdata\windows defender",
        r"c:\programdata\package cache",
        r"c:\programdata\dell",
        r"c:\programdata\intel",
        r"c:\programdata\nvidia",
        r"c:\programdata\amd",
        r"c:\programdata\realtek",
        r"c:\programdata\vmware",
        r"c:\windows",
        r"c:\program files",
    }
    SKIP_DIR_PATTERNS = [
        "_mei", "nsi", "nsc", "_pyinstaller", "pyinstaller",
        # Chrome/Edge isolated feature directories (Domain Actions, Well Known Domains, dll)
        "scoped_dir",
        # Chrome/Edge component updater temp
        "cr_", "chrome_",
        # Office Click-to-Run working dirs
        "officec2r",
        # Common vendor temp patterns (benign working folders)
        "msicache", "msocache",
    ]
    double_ext = [".exe", ".dll", ".bat", ".cmd", ".ps1", ".vbs", ".js", ".jar"]

    for d in scan_dirs:
        if not d or not os.path.isdir(d):
            continue
        try:
            for root, _, files in os.walk(d):
                root_lower   = root.lower()
                folder_name  = os.path.basename(root).lower()
                if any(root_lower.startswith(sd) for sd in SKIP_FILE_DIRS):
                    continue
                # Fix v2.0-alpha-M3.4: substring match SELURUH path, bukan hanya basename
                # (contoh: file di temp\scoped_dir41220\DomainActions\3.0.0.20\x.dll
                # — basename folder = '3.0.0.20', tidak akan match 'scoped_dir'.
                # Jadi check 'scoped_dir' anywhere in root path)
                if any(p in root_lower for p in SKIP_DIR_PATTERNS):
                    continue
                for fname in files:
                    fp         = os.path.join(root, fname)
                    flags      = []
                    fname_lower = fname.lower()
                    parts       = fname_lower.split(".")
                    if len(parts) > 2 and f".{parts[-1]}" in double_ext:
                        if f".{parts[-2]}" in [".pdf", ".doc", ".xls", ".txt", ".jpg"]:
                            flags.append("Ekstensi ganda (file menyamar)")
                    if fname_lower in WINDOWS_LEGITIMATE_DLLS:
                        continue
                    for ext in double_ext:
                        if fname_lower.endswith(ext):
                            flags.append(f"Executable di temp dir: {ext}")
                            break
                    if flags:
                        try:
                            size  = os.path.getsize(fp)
                            mtime = datetime.datetime.fromtimestamp(
                                os.path.getmtime(fp)).strftime("%Y-%m-%d %H:%M:%S")
                            # Full-file hash (MD5 + SHA256 untuk file <= 50MB), truncate kalau > 50MB
                            md5_h = hashlib.md5()
                            sha256_h = hashlib.sha256()
                            try:
                                sz_check = os.path.getsize(fp)
                                do_sha256 = sz_check <= 50 * 1024 * 1024
                                with open(fp, "rb") as fh:
                                    while True:
                                        chunk = fh.read(1024 * 1024)
                                        if not chunk:
                                            break
                                        md5_h.update(chunk)
                                        if do_sha256:
                                            sha256_h.update(chunk)
                                md5 = md5_h.hexdigest()
                                sha256 = sha256_h.hexdigest() if do_sha256 else "(file>50MB, SHA256 skipped)"
                            except Exception:
                                md5 = "-"
                                sha256 = "-"
                        except:
                            size, mtime, md5, sha256 = 0, "-", "-", "-"
                        severity = "HIGH" if "Ekstensi ganda" in " ".join(flags) else "MEDIUM"
                        size_kb  = round(size / 1024, 1)
                        entry    = {"path": fp, "size": size, "mtime": mtime,
                                    "md5": md5, "sha256": sha256,
                                    "flags": flags, "severity": severity}
                        file_list.append(entry)
                        add_finding(findings, severity,
                            f"File mencurigakan: {fname}",
                            f"Path: {fp} | Size: {size_kb} KB | Modified: {mtime} | MD5: {md5} | SHA256: {sha256[:16] + '...' if sha256 and len(sha256) > 16 else sha256} | {' | '.join(flags)}",
                            raw=json.dumps(entry, ensure_ascii=False))
        except PermissionError:
            continue
    return findings, file_list

# ── MODULE 5: EVENT LOGS ─────────────────────────────────────────────────────
def check_event_logs():
    findings = []
    event_list = []
    if not WMI_AVAILABLE:
        add_finding(findings, "INFO", "Event log check dilewati", "pywin32 tidak tersedia")
        return findings, event_list
    try:
        log_types = [("Security", [4625, 4648, 4720, 4732, 4728, 1102]),
                     ("System",   [7045, 7036]),
                     ("Application", [1000])]
        for log_name, event_ids in log_types:
            try:
                hand = win32evtlog.OpenEventLog(None, log_name)
                flags = win32evtlog.EVENTLOG_BACKWARDS_READ | win32evtlog.EVENTLOG_SEQUENTIAL_READ
                total = 0
                while total < 500:
                    events = win32evtlog.ReadEventLog(hand, flags, 0)
                    if not events:
                        break
                    for ev in events:
                        if ev.EventID & 0xFFFF in event_ids:
                            eid = ev.EventID & 0xFFFF
                            t = ev.TimeGenerated.Format()
                            desc_map = {
                                4625: ("MEDIUM", "Gagal login"),
                                4648: ("HIGH",   "Login dengan kredensial eksplisit"),
                                4720: ("HIGH",   "Akun baru dibuat"),
                                4732: ("HIGH",   "User ditambah ke grup privileged"),
                                4728: ("HIGH",   "User ditambah ke grup privileged global"),
                                1102: ("CRITICAL","Event log dihapus"),
                                7045: ("HIGH",   "Service baru diinstall"),
                            }
                            sev, title = desc_map.get(eid, ("INFO", f"Event ID {eid}"))
                            entry = {"log": log_name, "event_id": eid,
                                     "time": t, "severity": sev}
                            event_list.append(entry)
                            add_finding(findings, sev,
                                f"{title} [{log_name}] Event {eid}",
                                f"Waktu: {t}",
                                raw=json.dumps(entry, ensure_ascii=False))
                    total += len(events)
                win32evtlog.CloseEventLog(hand)
            except Exception:
                continue
    except Exception as e:
        add_finding(findings, "INFO", "Event log error", str(e))
    return findings, event_list

# ── MODULE 6: USER ACCOUNTS ──────────────────────────────────────────────────
def check_user_accounts():
    findings = []
    user_list = []
    try:
        result = subprocess.run(['net', 'user'], capture_output=True, text=True)
        lines = result.stdout.splitlines()
        users = []
        capture = False
        for line in lines:
            if '---' in line:
                capture = not capture
                continue
            if capture and line.strip():
                users += line.split()

        admin_result = subprocess.run(['net', 'localgroup', 'administrators'],
                                       capture_output=True, text=True)
        admin_lines = admin_result.stdout.splitlines()
        admins = set()
        cap = False
        for line in admin_lines:
            if '---' in line:
                cap = True
                continue
            if cap and line.strip() and 'command' not in line.lower():
                admins.add(line.strip())

        # Fix v2.0-alpha-M3.4: lebih nuanced untuk admin accounts
        # - Jumlah admin ≤ 3 → INFO (wajar di PC personal: built-in Administrator + 1-2 user)
        # - Jumlah admin > 3 → MEDIUM (admin creep, perlu review)
        # - Jumlah admin > 5 → HIGH (anomali signifikan)
        # - Built-in "Administrator" account selalu INFO (default Windows)
        admin_count = len(admins)
        if admin_count > 5:
            base_sev = "HIGH"
        elif admin_count > 3:
            base_sev = "MEDIUM"
        else:
            base_sev = "INFO"

        for user in users:
            is_admin = user in admins
            flags = []
            if is_admin:
                flags.append("Member grup Administrators")
            # Built-in Administrator (SID RID 500) selalu INFO
            if user.lower() == "administrator":
                severity = "INFO"
            elif is_admin:
                severity = base_sev
            else:
                severity = "INFO"
            entry = {"username": user, "is_admin": is_admin,
                     "flags": flags, "severity": severity,
                     "total_admin_count": admin_count}
            user_list.append(entry)
            if is_admin:
                detail_extra = f" | Total admin accounts: {admin_count}"
                if admin_count > 3:
                    detail_extra += " (anomali — admin creep)"
                add_finding(findings, severity,
                    f"User dengan privilege admin: {user}",
                    " | ".join(flags) + detail_extra,
                    raw=json.dumps(entry, ensure_ascii=False))
    except Exception as e:
        add_finding(findings, "INFO", "User account check error", str(e))
    return findings, user_list

# ── MODULE 7: DNS CACHE ──────────────────────────────────────────────────────
def check_dns_cache():
    findings = []
    dns_list = []
    try:
        result = subprocess.run(['ipconfig', '/displaydns'],
                                capture_output=True, text=True, timeout=15)
        current_domain = None
        for line in result.stdout.splitlines():
            line = line.strip()
            if 'Record Name' in line:
                current_domain = line.split(':')[-1].strip()
            if 'A (Host) Record' in line and current_domain:
                ip = line.split(':')[-1].strip()
                flags = []
                typos = ['g00gle','g00gl','faceb00k','micros0ft','paypa1','arnaz0n']
                for t in typos:
                    if t in current_domain.lower():
                        flags.append(f"Domain typosquatting: {t}")
                if ip.startswith(('127.','0.0.0.')) and not current_domain.startswith('localhost'):
                    flags.append("Domain resolve ke loopback — kemungkinan hosts file manipulation")
                severity = "HIGH" if flags else "INFO"
                entry = {"domain": current_domain, "ip": ip,
                         "flags": flags, "severity": severity}
                dns_list.append(entry)
                if flags:
                    add_finding(findings, severity,
                        f"DNS mencurigakan: {current_domain}",
                        " | ".join(flags),
                        raw=json.dumps(entry, ensure_ascii=False))
    except Exception as e:
        add_finding(findings, "INFO", "DNS cache check error", str(e))
    return findings, dns_list

# ── MODULE 8: DLL & DRIVERS ──────────────────────────────────────────────────
def check_dll_drivers():
    findings = []
    dll_list = []
    try:
        for proc in psutil.process_iter(['pid', 'name']):
            try:
                maps = proc.memory_maps()
                for m in maps:
                    path = m.path.lower()
                    if path.endswith('.dll'):
                        flags = []
                        is_sys_dll = any(path.startswith(lp) for lp in WINDOWS_LEGITIMATE_PATHS)
                        if is_sys_dll:
                            continue
                        for sp in SUSPICIOUS_PATHS:
                            if sp and sp.lower() in path:
                                flags.append(f"DLL dari path mencurigakan: {sp}")
                        if flags:
                            entry = {"proc": proc.info['name'], "pid": proc.info['pid'],
                                     "dll": m.path, "flags": flags, "severity": "HIGH"}
                            dll_list.append(entry)
                            add_finding(findings, "HIGH",
                                f"DLL mencurigakan di {proc.info['name']} (PID {proc.info['pid']})",
                                f"DLL Path: {m.path} | Process: {proc.info['name']} | {' | '.join(flags)}",
                                raw=json.dumps(entry, ensure_ascii=False))
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
    except Exception as e:
        add_finding(findings, "INFO", "DLL check error", str(e))

    try:
        import csv as _csv
        import io as _io
        result = subprocess.run(['driverquery', '/fo', 'csv', '/v'],
                                capture_output=True, text=True, timeout=30)
        reader = _csv.reader(_io.StringIO(result.stdout))
        rows = list(reader)
        for parts in rows[1:]:
            if len(parts) > 5:
                drv_name = parts[0]
                drv_path = parts[5] if len(parts) > 5 else ''
                flags = []
                for sp in SUSPICIOUS_PATHS:
                    if sp and sp.lower() in drv_path.lower():
                        flags.append("Driver dari path tidak wajar")
                if flags:
                    entry = {"name": drv_name, "path": drv_path,
                             "flags": flags, "severity": "CRITICAL"}
                    dll_list.append(entry)
                    add_finding(findings, "CRITICAL",
                        f"Driver mencurigakan: {drv_name}",
                        " | ".join(flags),
                        raw=json.dumps(entry, ensure_ascii=False))
    except Exception as e:
        add_finding(findings, "INFO", "Driver check error", str(e))
    return findings, dll_list

# ── MODULE 9: BROWSER ARTIFACTS ──────────────────────────────────────────────
def check_browser_artifacts():
    findings = []
    browser_list = []
    browser_paths = {
        "Chrome":  os.path.join(os.environ.get("LOCALAPPDATA",""), r"Google\Chrome\User Data\Default"),
        "Edge":    os.path.join(os.environ.get("LOCALAPPDATA",""), r"Microsoft\Edge\User Data\Default"),
        "Firefox": os.path.join(os.environ.get("APPDATA",""), r"Mozilla\Firefox\Profiles"),
    }
    for browser, base_path in browser_paths.items():
        if not os.path.isdir(base_path):
            continue
        ext_path = os.path.join(base_path, "Extensions") if browser != "Firefox" else base_path
        if os.path.isdir(ext_path):
            try:
                exts = os.listdir(ext_path)
                entry = {"browser": browser, "extensions_count": len(exts),
                         "extensions": exts[:20], "severity": "INFO"}
                browser_list.append(entry)
                if len(exts) > 10:
                    add_finding(findings, "MEDIUM",
                        f"{browser}: Jumlah ekstensi tinggi ({len(exts)})",
                        "Periksa ekstensi yang tidak dikenal secara manual",
                        raw=json.dumps(entry, ensure_ascii=False))
            except Exception:
                pass
        hist_db = os.path.join(base_path, "History")
        if os.path.isfile(hist_db):
            tmp_db = os.path.join(tempfile.gettempdir(), f"_audit_{browser}_hist.db")
            try:
                shutil.copy2(hist_db, tmp_db)
                conn = sqlite3.connect(tmp_db)
                cur = conn.cursor()
                cur.execute("SELECT url, title, visit_count FROM urls ORDER BY visit_count DESC LIMIT 20")
                rows = cur.fetchall()
                conn.close()
                os.remove(tmp_db)
                suspicious_domains = ['pastebin','ngrok','transfer.sh','webhook.site','requestbin']
                for url, title, count in rows:
                    for sd in suspicious_domains:
                        if sd in (url or '').lower():
                            entry = {"browser": browser, "url": url,
                                     "visit_count": count, "severity": "HIGH"}
                            browser_list.append(entry)
                            add_finding(findings, "HIGH",
                                f"{browser}: Akses ke domain mencurigakan",
                                f"{url} (dikunjungi {count}x)",
                                raw=json.dumps(entry, ensure_ascii=False))
            except Exception:
                pass
    return findings, browser_list

# ── MODULE 10: WMI SUBSCRIPTIONS ─────────────────────────────────────────────
def check_wmi_subscriptions():
    findings = []
    wmi_list = []
    if not WMI_AVAILABLE:
        add_finding(findings, "INFO", "WMI subscription check dilewati", "wmi tidak tersedia")
        return findings, wmi_list
    try:
        c = wmi.WMI(namespace="root\\subscription")
        LEGIT_WMI = {
            "scm event log filter","scm event log consumer",
            "bvtfilter","nteventlogconsumer","filtertoconsumerbinding",
            "windows event log","microsoft windows",
        }
        for obj in c.query("SELECT * FROM __EventFilter"):
            if obj.Name.lower() in LEGIT_WMI:
                continue
            entry = {"type": "__EventFilter", "name": obj.Name,
                     "query": obj.Query, "severity": "HIGH"}
            wmi_list.append(entry)
            add_finding(findings, "HIGH",
                f"WMI EventFilter ditemukan: {obj.Name}",
                f"Query: {obj.Query}",
                raw=json.dumps(entry, ensure_ascii=False))
        for obj in c.query("SELECT * FROM __EventConsumer"):
            if obj.Name.lower() in LEGIT_WMI:
                continue
            entry = {"type": "__EventConsumer", "name": obj.Name, "severity": "HIGH"}
            wmi_list.append(entry)
            add_finding(findings, "HIGH",
                f"WMI EventConsumer ditemukan: {obj.Name}",
                "Persistence via WMI consumer",
                raw=json.dumps(entry, ensure_ascii=False))
    except Exception as e:
        add_finding(findings, "INFO", "WMI subscription check error", str(e))
    return findings, wmi_list

# ── MODULE 11: PREFETCH ───────────────────────────────────────────────────────
def check_prefetch():
    findings = []
    prefetch_list = []
    pf_dir = r"C:\Windows\Prefetch"
    if not os.path.isdir(pf_dir):
        add_finding(findings, "INFO", "Prefetch tidak tersedia", "Mungkin dinonaktifkan")
        return findings, prefetch_list
    try:
        for fname in os.listdir(pf_dir):
            if not fname.endswith('.pf'):
                continue
            fp = os.path.join(pf_dir, fname)
            exe_name = fname.split('-')[0].lower()
            flags = []
            mtime = datetime.datetime.fromtimestamp(os.path.getmtime(fp)).strftime('%Y-%m-%d %H:%M:%S')
            LEGIT_PREFETCH = {
                "filesynchelper.exe","filesyncconfig.exe","filecoauth.exe",
                "onedrive.exe","onedrive.sync.service.exe","odauth.exe",
                "phoneexperiencehost.exe","shellexperiencehost.exe",
                "startmenuexperiencehost.exe","openconsole.exe",
                "gpu_encoder_helper.exe","mobsync.exe",
                "searchhost.exe","searchindexer.exe","searchprotocolhost.exe",
                "backgroundtransferhost.exe","backgroundtaskhost.exe",
                "runtimebroker.exe","applicationframehost.exe",
                "wuauclt.exe","musnotification.exe","wusa.exe",
                "sihost.exe","taskhostw.exe","ctfmon.exe",
                "securityhealthsystray.exe","securityhealthservice.exe",
                "useroobebroker.exe","lockapp.exe","logonui.exe",
                "compattelrunner.exe","wsappx.exe","wermgr.exe",
            }
            if exe_name in LEGIT_PREFETCH:
                continue
            for bad in SUSPICIOUS_PROCESS_NAMES:
                if bad in exe_name:
                    flags.append(f"Nama binary mencurigakan: {exe_name}")
            severity = "CRITICAL" if flags else "INFO"
            entry = {"file": fname, "exe": exe_name,
                     "last_run": mtime, "flags": flags, "severity": severity}
            prefetch_list.append(entry)
            if flags:
                add_finding(findings, severity,
                    f"Prefetch binary mencurigakan: {exe_name}",
                    f"Terakhir dijalankan: {mtime} | " + " | ".join(flags),
                    raw=json.dumps(entry, ensure_ascii=False))
    except PermissionError as e:
        add_finding(findings, "INFO",
                    "Prefetch tidak bisa dibaca (permission denied)",
                    "Butuh privilege Administrator untuk membaca C:\\Windows\\Prefetch. "
                    "Pastikan EXE dijalankan dengan 'Run as Administrator'.",
                    raw=json.dumps({"error": str(e), "action": "run_as_admin"}))
    except Exception as e:
        add_finding(findings, "INFO", "Prefetch check error", str(e))
    return findings, prefetch_list

# ── MODULE 12: ARP CACHE ─────────────────────────────────────────────────────
def check_arp_cache():
    findings = []
    arp_list = []
    try:
        result = subprocess.run(['arp', '-a'], capture_output=True, text=True, timeout=10)
        mac_map = {}
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) >= 2:
                ip = parts[0]
                mac = parts[1] if len(parts) > 1 else ''
                if mac and mac != 'ff-ff-ff-ff-ff-ff':
                    if mac in mac_map and mac_map[mac] != ip:
                        entry = {"ip1": mac_map[mac], "ip2": ip,
                                 "mac": mac, "severity": "HIGH"}
                        arp_list.append(entry)
                        add_finding(findings, "HIGH",
                            f"Kemungkinan ARP spoofing: MAC {mac}",
                            f"IP ganda: {mac_map[mac]} dan {ip}",
                            raw=json.dumps(entry, ensure_ascii=False))
                    mac_map[mac] = ip
                entry = {"ip": ip, "mac": mac, "severity": "INFO"}
                arp_list.append(entry)
    except Exception as e:
        add_finding(findings, "INFO", "ARP check error", str(e))
    return findings, arp_list

