# ── MODULE 13 [VA-03]: SECURITY FEATURE POSTURE ──────────────────────────────
def check_security_posture():
    """Audit konfigurasi fitur keamanan built-in Windows (Defender, UAC, Firewall, dll)."""
    findings = []
    posture_list = []

    def _reg_read(hive, path, name):
        try:
            k = winreg.OpenKey(hive, path)
            val, _ = winreg.QueryValueEx(k, name)
            winreg.CloseKey(k)
            return val
        except Exception:
            return None

    def _add(severity, title, detail, key, value, expected, actual):
        entry = {
            "check": title, "key": key, "value_name": value,
            "expected": str(expected), "actual": str(actual),
            "severity": severity
        }
        posture_list.append(entry)
        add_finding(findings, severity, title, detail,
                    raw=json.dumps(entry, ensure_ascii=False))

    # ── Windows Defender Real-time Protection ───────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection",
                  "DisableRealtimeMonitoring")
    if v == 1:
        _add("CRITICAL", "Defender Real-time Protection DISABLED",
             "Realtime protection dinonaktifkan via policy — endpoint tanpa proteksi aktif",
             r"HKLM\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection",
             "DisableRealtimeMonitoring", "0 (enabled)", v)
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
                  "DisableRealtimeMonitoring")
    if v == 1:
        _add("CRITICAL", "Defender Real-time Protection DISABLED (lokal)",
             "Realtime protection dimatikan — segera aktifkan",
             r"HKLM\SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
             "DisableRealtimeMonitoring", "0", v)

    # ── Defender Tamper Protection ──────────────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SOFTWARE\Microsoft\Windows Defender\Features",
                  "TamperProtection")
    if v is not None and v != 5:
        _add("HIGH", "Defender Tamper Protection tidak aktif",
             "Tamper protection off — attacker bisa disable Defender dari dalam",
             r"HKLM\SOFTWARE\Microsoft\Windows Defender\Features",
             "TamperProtection", "5 (enabled)", v)

    # ── Defender Behavior Monitoring ────────────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
                  "DisableBehaviorMonitoring")
    if v == 1:
        _add("HIGH", "Defender Behavior Monitoring DISABLED",
             "Behavior monitoring off — deteksi heuristic nonaktif",
             r"HKLM\SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
             "DisableBehaviorMonitoring", "0", v)

    # ── Defender Script Scanning ────────────────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
                  "DisableScriptScanning")
    if v == 1:
        _add("HIGH", "Defender Script Scanning DISABLED",
             "Script scanning off — PowerShell/VBS/JS payload tidak di-scan",
             r"HKLM\SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
             "DisableScriptScanning", "0", v)

    # ── Defender Exclusions (path yang user-writable = HIGH) ────────────────
    for sub in [r"SOFTWARE\Microsoft\Windows Defender\Exclusions\Paths",
                r"SOFTWARE\Microsoft\Windows Defender\Exclusions\Processes",
                r"SOFTWARE\Microsoft\Windows Defender\Exclusions\Extensions"]:
        try:
            k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, sub)
            i = 0
            while True:
                try:
                    name, _, _ = winreg.EnumValue(k, i)
                    is_user_path = any(
                        name.lower().startswith(p)
                        for p in [r"c:\users\\", r"c:\temp", r"c:\programdata\temp",
                                  r"%temp%", r"%appdata%", r"%localappdata%"]
                    )
                    is_dangerous_ext = name.lower() in [".exe", ".dll", ".ps1", ".bat", ".cmd", ".vbs", ".js"]
                    if is_user_path:
                        _add("HIGH", f"Defender exclusion di user-writable path",
                             f"Exclusion: {name} — attacker bisa drop malware di sini bypass AV",
                             sub, "exclusion", "(none / vendor-only)", name)
                    elif is_dangerous_ext:
                        _add("CRITICAL", f"Defender exclusion ekstensi berbahaya",
                             f"Exclusion: {name} — semua file ekstensi ini bypass AV",
                             sub, "exclusion", "(none)", name)
                    else:
                        entry = {"check": "Defender exclusion", "value": name,
                                 "severity": "INFO"}
                        posture_list.append(entry)
                    i += 1
                except OSError:
                    break
            winreg.CloseKey(k)
        except Exception:
            pass

    # ── UAC Status ──────────────────────────────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System",
                  "EnableLUA")
    if v == 0:
        _add("CRITICAL", "UAC (User Account Control) DISABLED",
             "UAC mati total — semua proses jalan dengan hak administrator tanpa prompt",
             r"HKLM\...\Policies\System", "EnableLUA", "1", v)
    v2 = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                   r"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System",
                   "ConsentPromptBehaviorAdmin")
    if v2 == 0:
        _add("HIGH", "UAC Admin Prompt disabled",
             "Admin elevation tidak minta konfirmasi — UAC praktis bypass",
             r"HKLM\...\Policies\System", "ConsentPromptBehaviorAdmin", "5 (secure)", v2)

    # ── LSA Protection (RunAsPPL) ───────────────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SYSTEM\CurrentControlSet\Control\Lsa", "RunAsPPL")
    if not v or v == 0:
        _add("HIGH", "LSA Protection (RunAsPPL) tidak aktif",
             "Tanpa RunAsPPL, LSASS bisa di-dump oleh Mimikatz untuk credential theft",
             r"HKLM\SYSTEM\CurrentControlSet\Control\Lsa", "RunAsPPL", "1 or 2", v)

    # ── Firewall profiles via netsh ─────────────────────────────────────────
    try:
        r = subprocess.run(['netsh', 'advfirewall', 'show', 'allprofiles', 'state'],
                           capture_output=True, text=True, timeout=10)
        import re as _re
        # Cari profile dengan state OFF
        current_profile = None
        for line in r.stdout.splitlines():
            line = line.strip()
            m_prof = _re.match(r'^(Domain|Private|Public|Domain Profile|Private Profile|Public Profile)', line, _re.I)
            if m_prof:
                current_profile = m_prof.group(1)
            if current_profile and ("OFF" in line.upper() and "State" in line):
                _add("HIGH", f"Firewall profile '{current_profile}' OFF",
                     f"Firewall nonaktif di profile {current_profile} — endpoint terbuka ke jaringan",
                     "netsh advfirewall", f"state ({current_profile})", "ON", "OFF")
    except Exception as e:
        add_finding(findings, "INFO", "Firewall check error", str(e))

    # ── SMBv1 enabled ───────────────────────────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters",
                  "SMB1")
    if v is None or v == 1:
        # Belum tentu, perlu cek lebih dalam via PowerShell
        try:
            r = subprocess.run(
                ['powershell', '-NoProfile', '-Command',
                 "(Get-SmbServerConfiguration -ErrorAction SilentlyContinue).EnableSMB1Protocol"],
                capture_output=True, text=True, timeout=15)
            out = r.stdout.strip().lower()
            if out == "true":
                _add("CRITICAL", "SMBv1 enabled",
                     "SMBv1 aktif — rentan EternalBlue (WannaCry/NotPetya vector). Wajib disable.",
                     "SmbServerConfiguration", "EnableSMB1Protocol", "False", "True")
        except Exception:
            pass

    # ── WDigest plaintext (classic Mimikatz enabler) ────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest",
                  "UseLogonCredential")
    if v == 1:
        _add("CRITICAL", "WDigest plaintext credential ENABLED",
             "UseLogonCredential=1 — password plaintext ter-cache di LSASS, Mimikatz-ready",
             r"HKLM\SYSTEM\...\WDigest", "UseLogonCredential", "0 or absent", v)

    # ── NTLMv1 level (LmCompatibilityLevel) ─────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SYSTEM\CurrentControlSet\Control\Lsa",
                  "LmCompatibilityLevel")
    if v is not None and v < 3:
        _add("HIGH", "NTLMv1 masih di-allow",
             f"LmCompatibilityLevel={v} — NTLMv1 masih diterima (vulnerable ke relay & crack)",
             r"HKLM\SYSTEM\CurrentControlSet\Control\Lsa",
             "LmCompatibilityLevel", "3 or higher", v)

    # ── LM Hash stored ──────────────────────────────────────────────────────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SYSTEM\CurrentControlSet\Control\Lsa",
                  "NoLMHash")
    if v == 0:
        _add("HIGH", "LM Hash disimpan",
             "LM hash (MD4 broken) masih disimpan untuk password lama — mudah di-crack",
             r"HKLM\SYSTEM\...\Lsa", "NoLMHash", "1", v)

    # Catat INFO entry untuk posture summary
    entry_summary = {"check": "Security Posture Summary",
                     "total_checks_run": len(posture_list),
                     "severity": "INFO"}
    posture_list.append(entry_summary)

    return findings, posture_list


