def check_hacking_tools():
    """Deteksi hacking/pentest tools yang terinstall atau pernah dijalankan."""
    findings = []
    tools_found = []

    def _flag(name, category, severity, source, extra=""):
        entry = {"tool": name, "category": category, "detected_via": source,
                 "extra": extra, "severity": severity}
        tools_found.append(entry)
        add_finding(findings, severity,
                    f"Hacking tool terdeteksi: {name}",
                    f"Kategori: {category} | Terdeteksi via: {source} | {extra}",
                    raw=json.dumps(entry, ensure_ascii=False))

    # 1) Scan registry Uninstall
    uninstall_keys = [
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_CURRENT_USER,  r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
    ]
    for hive, path in uninstall_keys:
        try:
            k = winreg.OpenKey(hive, path)
            i = 0
            while True:
                try:
                    sub = winreg.EnumKey(k, i)
                    i += 1
                    try:
                        sk = winreg.OpenKey(k, sub)
                        try:
                            dn, _ = winreg.QueryValueEx(sk, "DisplayName")
                            dn_lower = dn.lower()
                            for sig, (cat, sev) in HACKING_TOOLS_SIGNATURES.items():
                                if sig in dn_lower:
                                    _flag(dn, cat, sev, "Registry Uninstall",
                                          f"Entry: {sub}")
                                    break
                        except Exception:
                            pass
                        winreg.CloseKey(sk)
                    except Exception:
                        continue
                except OSError:
                    break
            winreg.CloseKey(k)
        except Exception:
            continue

    # 2) Scan running processes
    try:
        for proc in psutil.process_iter(['name', 'exe', 'pid']):
            try:
                name = (proc.info.get('name') or '').lower()
                exe  = (proc.info.get('exe') or '').lower()
                for sig, (cat, sev) in HACKING_TOOLS_SIGNATURES.items():
                    if sig in name or sig in exe:
                        _flag(proc.info['name'], cat, sev, "Running Process",
                              f"PID: {proc.info['pid']} | Path: {proc.info.get('exe','-')}")
                        break
            except Exception:
                continue
    except Exception:
        pass

    # 3) Scan common install folders
    scan_dirs = [
        os.environ.get("ProgramFiles", r"C:\Program Files"),
        os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"),
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs"),
    ]
    for base in scan_dirs:
        if not base or not os.path.isdir(base):
            continue
        try:
            for folder in os.listdir(base):
                folder_lower = folder.lower()
                for sig, (cat, sev) in HACKING_TOOLS_SIGNATURES.items():
                    if sig in folder_lower:
                        _flag(folder, cat, sev, "Install Folder",
                              f"Path: {os.path.join(base, folder)}")
                        break
        except PermissionError:
            continue
        except Exception:
            continue

    # 4) Scan Prefetch untuk jejak eksekusi historis (bahkan kalau sudah dihapus)
    pf_dir = r"C:\Windows\Prefetch"
    if os.path.isdir(pf_dir):
        try:
            for fname in os.listdir(pf_dir):
                if not fname.endswith('.pf'):
                    continue
                exe_name = fname.split('-')[0].lower()
                for sig, (cat, sev) in HACKING_TOOLS_SIGNATURES.items():
                    if sig in exe_name:
                        _flag(exe_name, cat, sev, "Prefetch (pernah dijalankan)",
                              f"File: {fname}")
                        break
        except Exception:
            pass

    return findings, tools_found


