    findings = []
    pirated_list = []

    def _flag(sev, title, detail, extra):
        # Auto-merge extra info ke detail kalau belum ada, supaya PATH/lokasi
        # langsung terlihat di main row tanpa perlu klik "Lihat detail".
        if extra and isinstance(extra, str):
            if extra not in detail:
                detail = f"{detail} | {extra}"
        entry = {"check": title, "detail": detail, "extra": extra, "severity": sev}
        pirated_list.append(entry)
        add_finding(findings, sev, title, detail,
                    raw=json.dumps(entry, ensure_ascii=False))

    # ── 1) KMS Activator Detection ──────────────────────────────────────────
    # 1a) Service name
    try:
        import csv as _csv, io as _io
        r = subprocess.run(['sc', 'query', 'type=', 'service', 'state=', 'all'],
                           capture_output=True, text=True, timeout=30)
        for line in r.stdout.splitlines():
            if 'SERVICE_NAME' in line:
                svc = line.split(':', 1)[-1].strip().lower()
                for sig in KMS_ACTIVATOR_SIGNATURES:
                    if sig in svc:
                        _flag("CRITICAL",
                              f"KMS activator service terdeteksi: {svc}",
                              f"Service aktivator ilegal — indikasi Windows/Office bajakan",
                              f"Service name: {svc}, signature match: {sig}")
                        break
    except Exception:
        pass

    # 1b) Scheduled task name
    try:
        import csv as _csv, io as _io
        r = subprocess.run(['schtasks', '/query', '/fo', 'CSV'],
                           capture_output=True, text=True, timeout=30)
        reader = _csv.reader(_io.StringIO(r.stdout))
        for row in list(reader)[1:]:
            if not row:
                continue
            task = row[0].lower()
            for sig in KMS_ACTIVATOR_SIGNATURES:
                if sig in task:
                    _flag("CRITICAL",
                          f"KMS activator scheduled task: {row[0]}",
                          "Scheduled task aktivator — aktivasi KMS berjalan otomatis",
                          f"Task: {row[0]}, signature: {sig}")
                    break
    except Exception:
        pass

