    for base in [r"C:\Windows\AAct_Tools", r"C:\Windows\KMS", r"C:\Windows\KMSAuto",
                 r"C:\ProgramData\KMS", r"C:\ProgramData\KMSAuto"]:
        if os.path.isdir(base):
            _flag("CRITICAL",
                  f"Folder KMS activator: {base}",
                  "Folder aktivator KMS di lokasi tersembunyi",
                  f"Path: {base}")

    # ── 2) Windows Activation Status ────────────────────────────────────────
    try:
        r = subprocess.run(['cscript', '//nologo', r'C:\Windows\System32\slmgr.vbs', '/dlv'],
                           capture_output=True, text=True, timeout=30)
        out = r.stdout
        if "Notification Reason" in out or "Notification mode" in out.lower():
            _flag("CRITICAL",
                  "Windows TIDAK terativasi (Notification mode)",
                  "Windows dalam notification mode — lisensi belum aktif atau cracked",
                  "slmgr.vbs /dlv output")
        if "grace" in out.lower() and "grace period remaining" in out.lower():
            _flag("HIGH",
                  "Windows dalam Grace Period",
                  "Windows grace period — trial atau pre-activation",
                  "slmgr.vbs /dlv output")
        # KMS server pointing to localhost = CRACK CONFIRMED
        for line in out.splitlines():
            if "key management service machine name" in line.lower() or \
               "nama mesin layanan manajemen kunci" in line.lower():
                kms_host = line.split(':', 1)[-1].strip().lower()
                if "localhost" in kms_host or "127.0.0.1" in kms_host:
                    _flag("CRITICAL",
                          "Windows KMS server = localhost",
                          "Aktivasi KMS point ke 127.0.0.1 — konfirmasi crack/KMS emulator lokal",
                          f"KMS Host: {kms_host}")
    except Exception as e:
        add_finding(findings, "INFO", "Windows activation check error", str(e))

