def check_missing_patches():
    """Audit missing security patches dan Windows EOL status."""
    findings = []
    patch_list = []

    # ── 1) Windows Build & EOL Check ────────────────────────────────────────
    try:
        k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                           r"SOFTWARE\Microsoft\Windows NT\CurrentVersion")
        build_num = None
        try:
            build_num, _ = winreg.QueryValueEx(k, "CurrentBuildNumber")
        except Exception:
            pass
        try:
            ubr, _ = winreg.QueryValueEx(k, "UBR")
        except Exception:
            ubr = None
        try:
            display_version, _ = winreg.QueryValueEx(k, "DisplayVersion")
        except Exception:
            display_version = None
        try:
            product_name, _ = winreg.QueryValueEx(k, "ProductName")
        except Exception:
            product_name = "Unknown"
        winreg.CloseKey(k)

        full_build = f"{build_num}.{ubr}" if ubr else build_num
        entry = {
            "check": "Windows Version",
            "product": product_name,
            "build": full_build,
            "display_version": display_version,
            "severity": "INFO"
        }

        if build_num in WINDOWS_EOL_STATUS:
            friendly, is_eol, note = WINDOWS_EOL_STATUS[build_num]
            entry["friendly"] = friendly
            entry["eol"] = is_eol
            entry["note"] = note
            if is_eol:
                entry["severity"] = "CRITICAL"
                patch_list.append(entry)
                add_finding(findings, "CRITICAL",
                            f"Windows version END-OF-LIFE: {friendly}",
                            f"Build {full_build} — {note} — tidak menerima security update",
                            raw=json.dumps(entry, ensure_ascii=False))
            else:
                patch_list.append(entry)
                add_finding(findings, "INFO",
                            f"Windows version: {friendly}",
                            f"Build {full_build} — {note}",
                            raw=json.dumps(entry, ensure_ascii=False))
        else:
            entry["note"] = "Build tidak ada di database EOL — periksa manual"
            patch_list.append(entry)
            add_finding(findings, "INFO",
                        f"Windows build {full_build} tidak dikenal database",
                        f"Product: {product_name} — periksa EOL manual di Microsoft Lifecycle",
                        raw=json.dumps(entry, ensure_ascii=False))
    except Exception as e:
        add_finding(findings, "INFO", "Windows version check error", str(e))

    # ── 2) Installed Hotfix enumeration ─────────────────────────────────────
    installed_kbs = set()
    try:
        if WMI_AVAILABLE:
            c = wmi.WMI()
            for qfe in c.Win32_QuickFixEngineering():
                kb = qfe.HotFixID
                if kb:
                    installed_kbs.add(kb.upper())
            patch_list.append({
                "check": "Installed Hotfixes Count",
                "count": len(installed_kbs),
                "severity": "INFO"
            })
    except Exception as e:
        add_finding(findings, "INFO", "Hotfix enumeration error", str(e))

    # Fallback: pakai wmic kalau WMI gagal
    if not installed_kbs:
        try:
            r = subprocess.run(['wmic', 'qfe', 'get', 'HotFixID', '/format:csv'],
                               capture_output=True, text=True, timeout=30)
            for line in r.stdout.splitlines():
                line = line.strip()
                if line.startswith("KB"):
                    installed_kbs.add(line.split(',')[-1].strip().upper()
                                      if ',' in line else line.upper())
        except Exception:
            pass

    # ── 3) Cross-check dengan critical KB database ──────────────────────────
    # Determine current OS family untuk match applicability
    def _os_matches(target_os_str, current_build):
        """Check kalau KB target_os match dengan current build."""
        if not current_build:
            return True  # Unknown build — flag conservatively (akan jadi INFO summary saja)
        try:
            cb = int(current_build)
        except (TypeError, ValueError):
            return True
        target_lower = target_os_str.lower()
        # Win10 1607 / Server 2016 = build 14393
        # Win10 1809 = 17763, 1903 = 18362, 1909 = 18363, 2004 = 19041, 20H2 = 19042, 21H1 = 19043, 21H2 = 19044, 22H2 = 19045
        # Win11 21H2 = 22000, 22H2 = 22621, 23H2 = 22631, 24H2 = 26100
        # Win Server 2019 = 17763, 2022 = 20348
        is_win10 = 10240 <= cb <= 19050
        is_win11 = cb >= 22000
        is_win_server = cb in (14393, 17763, 20348, 25398) or (20348 <= cb < 22000)
        is_win7_or_older = cb < 7600 or False  # Very unlikely on modern tool
        is_win8 = False  # Also unlikely
        is_win2012 = cb in (9200, 9600)

        # Multi-match: kalau target_os berisi "multi" / "server" / nama ber-varian, flag
        if "multi" in target_lower:
            return True
        if "exchange" in target_lower:
            return False  # Workstation biasanya bukan Exchange server
        if "server" in target_lower and is_win_server:
            return True
        if "server" in target_lower and not is_win_server:
            return False  # Server KB tidak relevan untuk workstation
        # Match Win10/Win11 specific
        if "win10" in target_lower or "windows 10" in target_lower:
            if is_win10: return True
            # Win10 1607 KB masih relevan untuk Server 2016 (build 14393)
            if "1607" in target_lower and cb == 14393: return True
            return False
        if "win11" in target_lower or "windows 11" in target_lower:
            return is_win11
        # Win7/2008 KBs — tidak relevan di Win10/11
        if "win7" in target_lower or "2008" in target_lower:
            return cb < 10000  # Win7 = 7600/7601
        if "win8" in target_lower or "2012" in target_lower:
            return cb in (9200, 9600)
        if "2019" in target_lower:
            return cb == 17763
        # Fallback: assume applicable
        return True

    # Fix v2.0-alpha-M3.4: KB Supersedence Heuristic
    # Realita: Microsoft merilis cumulative update (CU) bulanan yang MENYERTAKAN
    # perbaikan security dari KB-KB lama. KB standalone sering tidak muncul di
    # `Get-HotFix` karena sudah di-rolled up ke CU terbaru.
    # Heuristik:
    # - Win11 (build >= 22000): KB dari tahun 2021-2023 kemungkinan sudah superseded
    #   via CU bulanan → downgrade ke INFO/LOW dengan note verifikasi
    # - Win10 22H2 (build 19045) atau lebih baru: KB 2021-2022 kemungkinan superseded
    # - Win10 lama atau EOL: flag sesuai severity asli
    def _is_likely_superseded(meta_entry, current_build):
        """Return True kalau KB kemungkinan sudah superseded via newer CU."""
        if not current_build:
            return False
        try:
            cb = int(current_build)
        except (TypeError, ValueError):
            return False
        try:
            cve_year = int(meta_entry.get("cve", "CVE-0000-0").split("-")[1])
        except (ValueError, IndexError):
            return False
        # Win11 modern (build 22000+): CVE 2021-2023 kemungkinan superseded
        if cb >= 22000 and cve_year <= 2023:
            return True
        # Win10 22H2 (19045): CVE 2021-2022 kemungkinan superseded
        if cb >= 19045 and cve_year <= 2022:
            return True
        return False

    def _downgrade_severity(orig_sev):
        """Downgrade severity 1 level untuk patches yang kemungkinan superseded."""
        mapping = {"CRITICAL": "LOW", "HIGH": "LOW", "MEDIUM": "LOW", "LOW": "INFO"}
        return mapping.get(orig_sev, "INFO")

    missing_critical = []
    likely_superseded = []
    skipped_not_applicable = 0
    for kb, meta in CRITICAL_KB_DATABASE.items():
        if kb not in installed_kbs:
            # Cek relevansi KB ke OS saat ini
            if not _os_matches(meta.get("os", ""), build_num):
                skipped_not_applicable += 1
                continue

            superseded = _is_likely_superseded(meta, build_num)
            effective_severity = _downgrade_severity(meta["severity"]) if superseded else meta["severity"]

            if superseded:
                likely_superseded.append((kb, meta))
                title = f"Patch {kb} (kemungkinan superseded via CU): {meta['cve']}"
                detail = (f"{meta['name']} — target OS: {meta['os']} — KB standalone tidak terpasang "
                          f"TAPI kemungkinan besar sudah ter-include via cumulative update "
                          f"(Win build {build_num}). VERIFIKASI MANUAL: buka 'winver' dan cek "
                          f"'Windows Update History' untuk CU terbaru.")
            else:
                missing_critical.append((kb, meta))
                title = f"Missing security patch: {kb} ({meta['cve']})"
                detail = f"{meta['name']} — target OS: {meta['os']} — KB tidak terpasang"

            entry = {
                "check": f"Missing {kb}",
                "kb": kb,
                "cve": meta["cve"],
                "name": meta["name"],
                "applicable_os": meta["os"],
                "severity": effective_severity,
                "original_severity": meta["severity"],
                "likely_superseded": superseded,
                "current_build": build_num,
            }
            patch_list.append(entry)
            add_finding(findings, effective_severity, title, detail,
                        raw=json.dumps(entry, ensure_ascii=False))

    # Summary dengan breakdown lebih detail
    if not missing_critical and not likely_superseded:
        add_finding(findings, "INFO",
                    "Semua critical KB applicable ter-install",
                    f"Sudah ter-install: {len(installed_kbs)} hotfix total | KB non-applicable di-skip: {skipped_not_applicable}",
                    raw=json.dumps({"total_installed": len(installed_kbs),
                                    "skipped_not_applicable": skipped_not_applicable}))
    else:
        detail_msg = (
            f"Total hotfix installed: {len(installed_kbs)} | "
            f"Missing (confirmed): {len(missing_critical)} | "
            f"Likely superseded (verifikasi manual): {len(likely_superseded)} | "
            f"Non-applicable (OS mismatch): {skipped_not_applicable}"
        )
        if missing_critical:
            detail_msg += " | ⚠️ Patches 'Missing (confirmed)' perlu segera diverifikasi dan dipasang"
        if likely_superseded:
            detail_msg += " | ℹ️ 'Likely superseded' = kemungkinan sudah via CU, cek Windows Update History"
        add_finding(findings, "INFO",
                    f"Patch audit summary",
                    detail_msg,
                    raw=json.dumps({"missing_count": len(missing_critical),
                                    "superseded_count": len(likely_superseded),
                                    "skipped_count": skipped_not_applicable,
                                    "total_installed": len(installed_kbs)}))

    return findings, patch_list


# ── MODULE 19 [VA-09]: LEGACY PROTOCOL & WEAK CRYPTO ─────────────────────────
def check_legacy_crypto():
    """Audit TLS/SSL version, weak ciphers, weak hash di SCHANNEL registry."""
    findings = []
    crypto_list = []

    def _add(sev, title, detail, data):
        entry = {"check": title, "detail": detail, "data": data, "severity": sev}
        crypto_list.append(entry)
        add_finding(findings, sev, title, detail,
                    raw=json.dumps(entry, ensure_ascii=False))

    SCHANNEL_BASE = r"SYSTEM\CurrentControlSet\Control\SecurityProviders\SCHANNEL"

    # ── 1) TLS/SSL Protocol versions ────────────────────────────────────────
    # Protocol dianggap "enabled" jika Enabled != 0 atau tidak di-set (default enabled kecuali TLS1.0/1.1 di Win10+)
    protocol_checks = [
        ("SSL 2.0", "Server", "CRITICAL", "SSL 2.0 server (deprecated, vulnerable to BEAST/POODLE)"),
        ("SSL 2.0", "Client", "CRITICAL", "SSL 2.0 client (deprecated)"),
        ("SSL 3.0", "Server", "CRITICAL", "SSL 3.0 server (vulnerable to POODLE)"),
        ("SSL 3.0", "Client", "CRITICAL", "SSL 3.0 client (POODLE vulnerable)"),
        ("TLS 1.0", "Server", "HIGH", "TLS 1.0 server (deprecated PCI-DSS, BEAST)"),
        ("TLS 1.0", "Client", "HIGH", "TLS 1.0 client (deprecated)"),
        ("TLS 1.1", "Server", "HIGH", "TLS 1.1 server (deprecated by major browsers)"),
        ("TLS 1.1", "Client", "HIGH", "TLS 1.1 client (deprecated)"),
    ]

    for proto, side, sev, desc in protocol_checks:
        key_path = f"{SCHANNEL_BASE}\\Protocols\\{proto}\\{side}"
        try:
            k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path)
            try:
                enabled, _ = winreg.QueryValueEx(k, "Enabled")
            except Exception:
                enabled = None
            try:
                disabled_by_default, _ = winreg.QueryValueEx(k, "DisabledByDefault")
            except Exception:
                disabled_by_default = None
            winreg.CloseKey(k)

            # Enabled: 0xFFFFFFFF or 1 = enabled; 0 = disabled
            # DisabledByDefault: 1 = disabled; 0 = enabled
            if enabled is not None and enabled != 0 and disabled_by_default != 1:
                _add(sev, f"{proto} {side} ENABLED", desc,
                     {"protocol": proto, "side": side,
                      "enabled": enabled, "disabled_by_default": disabled_by_default})
            elif enabled is None and disabled_by_default != 1:
                # Key exists but no Enabled value — ambiguous; flag INFO
                _add("INFO", f"{proto} {side} setting present without explicit disable",
                     "Periksa manual — Enabled value kosong, mungkin masih default-enabled",
                     {"protocol": proto, "side": side})
        except FileNotFoundError:
            # Key tidak ada = default behavior. Mayoritas Win10 22H2+ dan Win11 sudah
            # default-disable TLS 1.0/1.1 di client. Server-side masih bervariasi.
            # Supaya tidak noisy, hanya flag LOW (sekali per proto, bukan per side)
            # Dan hanya untuk TLS lama — SSL 2/3 memang sudah hard-disabled di Win10+
            if proto in ("TLS 1.0", "TLS 1.1") and side == "Server":
                _add("LOW", f"{proto} Server config tidak eksplisit di registry",
                     f"Registry key untuk {proto} Server tidak ada — {proto} mengikuti default OS. Disarankan explicit disable untuk compliance audit (PCI-DSS, CIS Benchmark).",
                     {"protocol": proto, "side": side, "status": "no explicit config"})
        except Exception:
            pass

    # ── 2) Weak Cipher Suites ───────────────────────────────────────────────
    weak_ciphers = [
        ("NULL",       "CRITICAL", "NULL cipher = no encryption at all"),
        ("RC4 40/128", "HIGH",     "RC4 40-bit (deprecated, broken)"),
        ("RC4 56/128", "HIGH",     "RC4 56-bit (deprecated)"),
        ("RC4 64/128", "HIGH",     "RC4 64-bit (deprecated)"),
        ("RC4 128/128","HIGH",     "RC4 128-bit (RFC 7465 prohibits RC4)"),
        ("DES 56/56",  "HIGH",     "DES 56-bit (cracked)"),
        ("Triple DES 168", "MEDIUM", "3DES (SWEET32 vulnerable)"),
    ]

    for cipher, sev, desc in weak_ciphers:
        key_path = f"{SCHANNEL_BASE}\\Ciphers\\{cipher}"
        try:
            k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path)
            try:
                enabled, _ = winreg.QueryValueEx(k, "Enabled")
            except Exception:
                enabled = None
            winreg.CloseKey(k)
            if enabled is None or enabled != 0:
                _add(sev, f"Weak cipher '{cipher}' tidak disabled",
                     desc,
                     {"cipher": cipher, "enabled": enabled})
        except FileNotFoundError:
            # Win10/11 secara default sudah disable NULL/RC4 di SCHANNEL meski tanpa
            # registry key eksplisit (hardcoded di schannel.dll). Flag "tidak explicit
            # disabled" bikin noisy tanpa risiko konkret — skip untuk kurangi FP.
            # Hanya flag kalau benar-benar explicit enabled (value != 0 di try block di atas).
            pass
        except Exception:
            pass

    # ── 3) Weak Hash Algorithms ─────────────────────────────────────────────
    weak_hashes = [
        ("MD5", "MEDIUM", "MD5 broken (collision attack feasible)"),
        ("SHA", "LOW",    "SHA-1 deprecated (SHAttered collision)"),
    ]
    for h, sev, desc in weak_hashes:
        key_path = f"{SCHANNEL_BASE}\\Hashes\\{h}"
        try:
            k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path)
            try:
                enabled, _ = winreg.QueryValueEx(k, "Enabled")
            except Exception:
                enabled = None
            winreg.CloseKey(k)
            if enabled is None or enabled != 0:
                _add(sev, f"Weak hash '{h}' tidak disabled di SCHANNEL",
                     desc,
                     {"hash": h, "enabled": enabled})
        except FileNotFoundError:
            pass
        except Exception:
            pass

    # ── 4) SMB Signing ──────────────────────────────────────────────────────
    # Fix v2.0-alpha-M3.4: hilangkan redundansi antara RequireSecuritySignature
    # dan EnableSecuritySignature. Kalau RequireSecuritySignature=0 sudah fire HIGH,
    # tidak perlu fire MEDIUM untuk EnableSecuritySignature (redundant message).
    # EnableSecuritySignature hanya di-flag sendiri kalau RequireSecuritySignature=1
    # (kontradiksi config: require ON tapi enable OFF)
    try:
        k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                           r"SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters")
        try:
            require_sign, _ = winreg.QueryValueEx(k, "RequireSecuritySignature")
        except Exception:
            require_sign = None
        try:
            enable_sign, _ = winreg.QueryValueEx(k, "EnableSecuritySignature")
        except Exception:
            enable_sign = None
        winreg.CloseKey(k)

        # Primary check: RequireSecuritySignature (lebih restrictive)
        if require_sign == 0:
            _add("HIGH", "SMB Signing NOT required (Server)",
                 "SMB signing tidak wajib — rentan SMB relay attack. "
                 "Set RequireSecuritySignature=1 (atau EnableSecuritySignature=1 untuk minimum)",
                 {"setting": "RequireSecuritySignature", "value": require_sign,
                  "enable_signature_also": enable_sign})
        # Secondary: Kontradiksi config (jarang terjadi, tapi worth noting)
        elif require_sign == 1 and enable_sign == 0:
            _add("MEDIUM", "SMB Signing config kontradiksi (Server)",
                 f"RequireSecuritySignature=1 tapi EnableSecuritySignature=0 — config aneh",
                 {"require": require_sign, "enable": enable_sign})
    except Exception:
        pass

    # SMB Client signing
    try:
        k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                           r"SYSTEM\CurrentControlSet\Services\LanmanWorkstation\Parameters")
        try:
            require_sign, _ = winreg.QueryValueEx(k, "RequireSecuritySignature")
            if require_sign == 0:
                _add("MEDIUM", "SMB Signing NOT required (Client)",
                     "SMB client signing tidak wajib",
                     {"setting": "RequireSecuritySignature (client)", "value": require_sign})
        except Exception:
            pass
        winreg.CloseKey(k)
    except Exception:
        pass

    # Summary INFO
    crypto_list.append({"check": "Legacy Crypto Scan Summary",
                        "total_issues": len([f for f in findings if f["severity"] in ("CRITICAL", "HIGH")]),
                        "severity": "INFO"})

    return findings, crypto_list


