# ── MODULE 23 [HMD-02]: FILELESS PERSISTENCE ─────────────────────────────────
def check_fileless_persistence():
    """Deteksi fileless malware: WMI full triplet, registry payload, BITS persistence."""
    findings = []
    fileless_list = []
    import math as _math
    from collections import Counter as _Counter

    def _add(sev, title, detail, data):
        entry = {"check": title, "detail": detail, "data": data, "severity": sev}
        fileless_list.append(entry)
        add_finding(findings, sev, title, detail,
                    raw=json.dumps(entry, ensure_ascii=False, default=str))

    def _entropy(b):
        if not b: return 0.0
        counts = _Counter(b)
        total = len(b)
        return -sum((c/total) * _math.log2(c/total) for c in counts.values())

    # ── 1) WMI Event Subscription FULL TRIPLET ──────────────────────────────
    # Yang paling kritis: __FilterToConsumerBinding (yang mengikat filter+consumer)
    if WMI_AVAILABLE:
        try:
            c = wmi.WMI(namespace="root\\subscription")

            LEGIT_WMI = {
                "scm event log filter", "scm event log consumer",
                "bvtfilter", "nteventlogconsumer", "filtertoconsumerbinding",
                "windows event log", "microsoft windows",
            }

            # Collect all filters & consumers first for cross-reference
            filters = {}
            for obj in c.query("SELECT * FROM __EventFilter"):
                filters[obj.Name] = {
                    "query": obj.Query,
                    "query_language": obj.QueryLanguage,
                }

            consumers = {}
            consumer_types = ["ActiveScriptEventConsumer",
                              "CommandLineEventConsumer",
                              "LogFileEventConsumer",
                              "NTEventLogEventConsumer",
                              "SMTPEventConsumer"]
            for ctype in consumer_types:
                try:
                    for obj in c.query(f"SELECT * FROM {ctype}"):
                        consumers[obj.Name] = {
                            "type": ctype,
                            "name": obj.Name,
                        }
                        # Extract payload per type
                        if ctype == "ActiveScriptEventConsumer":
                            consumers[obj.Name]["script_text"] = (obj.ScriptText or "")[:500]
                            consumers[obj.Name]["script_engine"] = obj.ScriptingEngine
                        elif ctype == "CommandLineEventConsumer":
                            consumers[obj.Name]["commandline"] = obj.CommandLineTemplate
                            consumers[obj.Name]["executable"] = obj.ExecutablePath
                except Exception:
                    continue

            # Check FilterToConsumerBinding (the "glue" that makes triplet functional)
            binding_count = 0
            for binding in c.query("SELECT * FROM __FilterToConsumerBinding"):
                binding_count += 1
                try:
                    # Reference format: 'namespace:__EventFilter.Name="X"'
                    filter_ref = str(binding.Filter) if binding.Filter else ""
                    consumer_ref = str(binding.Consumer) if binding.Consumer else ""

                    # Extract name from reference
                    import re as _re
                    filter_name_m = _re.search(r'Name="([^"]+)"', filter_ref)
                    consumer_name_m = _re.search(r'Name="([^"]+)"', consumer_ref)
                    filter_name = filter_name_m.group(1) if filter_name_m else "unknown"
                    consumer_name = consumer_name_m.group(1) if consumer_name_m else "unknown"

                    # Skip if both ends are legit system
                    if (filter_name.lower() in LEGIT_WMI and
                        consumer_name.lower() in LEGIT_WMI):
                        continue

                    filter_detail = filters.get(filter_name, {})
                    consumer_detail = consumers.get(consumer_name, {})

                    payload_str = ""
                    if consumer_detail.get("type") == "ActiveScriptEventConsumer":
                        payload_str = f" | Script engine: {consumer_detail.get('script_engine')} | Preview: {consumer_detail.get('script_text','')[:120]}"
                    elif consumer_detail.get("type") == "CommandLineEventConsumer":
                        payload_str = f" | CMD: {consumer_detail.get('commandline','')[:120]}"

                    _add("CRITICAL",
                         f"WMI PERSISTENCE AKTIF (full triplet): {filter_name} → {consumer_name}",
                         f"Filter query: {filter_detail.get('query','')[:100]} | Consumer type: {consumer_detail.get('type')}{payload_str}",
                         {"binding": {"filter": filter_name, "consumer": consumer_name},
                          "filter_detail": filter_detail,
                          "consumer_detail": consumer_detail})
                except Exception:
                    continue

            # Juga report orphan Filter/Consumer tanpa binding (bisa jadi sisa/deployment setengah)
            bound_filters = set()
            bound_consumers = set()
            try:
                for binding in c.query("SELECT * FROM __FilterToConsumerBinding"):
                    filter_ref = str(binding.Filter) if binding.Filter else ""
                    consumer_ref = str(binding.Consumer) if binding.Consumer else ""
                    fm = _re.search(r'Name="([^"]+)"', filter_ref)
                    cm = _re.search(r'Name="([^"]+)"', consumer_ref)
                    if fm: bound_filters.add(fm.group(1))
                    if cm: bound_consumers.add(cm.group(1))
            except Exception:
                pass

            for fname, fdata in filters.items():
                if fname.lower() in LEGIT_WMI or fname in bound_filters:
                    continue
                _add("HIGH",
                     f"WMI EventFilter orphan (tanpa binding): {fname}",
                     f"Query: {fdata.get('query','')[:150]} — filter ada tapi belum bound. Mungkin dalam proses deployment malware.",
                     {"filter_name": fname, "filter_detail": fdata})

            for cname, cdata in consumers.items():
                if cname.lower() in LEGIT_WMI or cname in bound_consumers:
                    continue
                _add("HIGH",
                     f"WMI EventConsumer orphan (tanpa binding): {cname}",
                     f"Type: {cdata.get('type')} — consumer ada tapi belum bound.",
                     {"consumer_name": cname, "consumer_detail": cdata})
        except Exception as e:
            add_finding(findings, "INFO", "WMI triplet check error", str(e))
    else:
        add_finding(findings, "INFO", "WMI triplet check skipped", "wmi/pywin32 tidak tersedia")

    # ── 2) Registry Payload Scan (high entropy REG_BINARY di lokasi mencurigakan) ─
    SCAN_LOCATIONS = [
        (winreg.HKEY_CURRENT_USER, r"Software\Classes\CLSID"),
        (winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_CURRENT_USER, r"Software"),  # top-level random subkeys
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"),
    ]

    PAYLOAD_SIZE_THRESHOLD = 1024    # 1 KB
    ENTROPY_THRESHOLD = 6.5          # Shellcode/encrypted biasanya > 6.5

    def _scan_key_for_payload(hive, path, max_depth=2, current_depth=0):
        if current_depth > max_depth:
            return
        try:
            k = winreg.OpenKey(hive, path)
            # Check values in this key
            i = 0
            while True:
                try:
                    name, val, typ = winreg.EnumValue(k, i)
                    i += 1
                    # REG_BINARY with large size + high entropy
                    if typ == winreg.REG_BINARY and val:
                        try:
                            data_len = len(val)
                            if data_len >= PAYLOAD_SIZE_THRESHOLD:
                                ent = _entropy(val[:4096])  # entropy of first 4KB
                                if ent >= ENTROPY_THRESHOLD:
                                    _add("HIGH",
                                         f"Registry payload mencurigakan (REG_BINARY)",
                                         f"Path: HKEY\\{path}\\{name} | Size: {data_len} bytes | Entropy: {ent:.2f} — kemungkinan shellcode/encrypted payload",
                                         {"hive": str(hive), "path": path, "value_name": name,
                                          "size": data_len, "entropy": round(ent, 2)})
                        except Exception:
                            pass
                    # REG_SZ with very long base64-like content
                    # Threshold dinaikkan ke 3000 char (v2.0-alpha-M3.4) — banyak app
                    # commercial (TikTok/ByteRtc, Zoom, Teams, Office) menyimpan config
                    # base64-encoded di range 1000-2000 char yang legitimate.
                    # Payload shellcode malware umumnya > 3000 char kalau cukup functional.
                    if typ == winreg.REG_SZ and isinstance(val, str) and len(val) > 3000:
                        # Base64 pattern: mostly alphanumeric + / + + = =
                        import re as _re
                        if _re.match(r'^[A-Za-z0-9+/\s=]{3000,}$', val):
                            # Whitelist path yang dikenal app commercial (legit config storage)
                            path_lower = path.lower()
                            LEGIT_APP_CONFIG_PATHS = [
                                "bytertcsdk", "tiktok", "bytedance",     # TikTok Live Studio
                                "zoom", "microsoft\\office\\",
                                "teams", "slack",
                                "adobe\\", "autodesk\\",
                                "jetbrains\\", "visualstudio\\",
                            ]
                            if any(p in path_lower for p in LEGIT_APP_CONFIG_PATHS):
                                continue  # Known vendor config storage — skip
                            _add("HIGH",
                                 f"Registry long base64-like string",
                                 f"Path: HKEY\\{path}\\{name} | Length: {len(val)} chars — kemungkinan base64 payload tersimpan",
                                 {"hive": str(hive), "path": path, "value_name": name,
                                  "length": len(val), "preview": val[:100]})
                except OSError:
                    break

            # Recurse into subkeys (limited depth to avoid full scan)
            if current_depth < max_depth:
                j = 0
                while True:
                    try:
                        sub = winreg.EnumKey(k, j); j += 1
                        _scan_key_for_payload(hive, f"{path}\\{sub}", max_depth, current_depth+1)
                    except OSError:
                        break
            winreg.CloseKey(k)
        except Exception:
            pass

    for hive, path in SCAN_LOCATIONS:
        _scan_key_for_payload(hive, path, max_depth=1)

    # ── 3) BITS Jobs Persistence ────────────────────────────────────────────
    try:
        r = subprocess.run(['bitsadmin', '/list', '/allusers', '/verbose'],
                           capture_output=True, text=True, timeout=30)
        out = r.stdout
        # Parse BITS output — looking for suspicious jobs
        # Fields of interest: JOB, STATE, NOTIFICATION COMMAND LINE, SUSPENDED
        current_job = {}
        suspicious_jobs = []
        for line in out.splitlines():
            line_s = line.strip()
            if not line_s:
                if current_job.get("Name"):
                    # Flag if notification cmdline exists atau state SUSPENDED with target URL
                    if (current_job.get("NotificationCmdLine") and
                        current_job["NotificationCmdLine"].lower() not in ("none", "n/a", "")):
                        suspicious_jobs.append(dict(current_job))
                    elif (current_job.get("State", "").upper() == "SUSPENDED" and
                          current_job.get("DisplayName")):
                        suspicious_jobs.append(dict(current_job))
                current_job = {}
                continue
            # Parse "KEY: value"
            if ':' in line_s:
                parts = line_s.split(':', 1)
                key = parts[0].strip().replace(" ", "")
                val = parts[1].strip() if len(parts) > 1 else ""
                # Keep interesting fields
                for target in ("DISPLAYNAME", "STATE", "NOTIFICATIONCOMMANDLINE", "JOB",
                               "OWNER", "PROXYUSAGE", "PRIORITY"):
                    if target.lower() in key.lower():
                        if target == "NOTIFICATIONCOMMANDLINE":
                            current_job["NotificationCmdLine"] = val
                        else:
                            current_job[target.title()] = val
                        break

        # Check last job if file doesn't end with blank line
        if current_job.get("Name") or current_job.get("Displayname"):
            if (current_job.get("NotificationCmdLine") and
                current_job["NotificationCmdLine"].lower() not in ("none", "n/a", "")):
                suspicious_jobs.append(dict(current_job))

        for job in suspicious_jobs:
            _add("HIGH",
                 f"BITS job mencurigakan: {job.get('Displayname', 'unknown')}",
                 f"State: {job.get('State','?')} | NotificationCmdLine: {job.get('NotificationCmdLine','?')} | Owner: {job.get('Owner','?')}",
                 job)
    except Exception as e:
        add_finding(findings, "INFO", "BITS check error", str(e))

    return findings, fileless_list


