def check_signature_anomaly():
    """Deteksi driver/DLL unsigned atau vulnerable (BYOVD)."""
    findings = []
    sig_list = []

    def _add(sev, title, detail, data):
        entry = {"check": title, "detail": detail, "data": data, "severity": sev}
        sig_list.append(entry)
        add_finding(findings, sev, title, detail,
                    raw=json.dumps(entry, ensure_ascii=False, default=str))

    # ── 1) Driver Enumeration + Signature Check ─────────────────────────────
    try:
        import csv as _csv
        import io as _io
        r = subprocess.run(['driverquery', '/si', '/fo', 'csv'],
                           capture_output=True, text=True, timeout=30)
        reader = _csv.reader(_io.StringIO(r.stdout))
        rows = list(reader)
        if len(rows) > 1:
            header = rows[0]
            # Columns: DeviceName, InfName, IsSigned, Manufacturer
            try:
                signed_idx = header.index("IsSigned")
                name_idx   = header.index("DeviceName")
                mfg_idx    = header.index("Manufacturer")
            except ValueError:
                signed_idx, name_idx, mfg_idx = 2, 0, 3

            # Whitelist vendor driver yang "driverquery /si" sering salah lapor sebagai unsigned
            # karena tool legacy tidak detect semua chain of trust (Catalog-signed, cross-signed, dll)
            VENDOR_DRIVER_WHITELIST = (
                "microsoft", "intel", "amd", "nvidia", "nvidia corporation",
                "realtek", "dell", "hewlett-packard", "hp inc", "lenovo",
                "asus", "msi", "gigabyte", "qualcomm", "broadcom", "mediatek",
                "mcafee", "symantec", "bitdefender", "kaspersky", "avast", "eset",
                "trend micro", "sophos", "crowdstrike", "sentinelone", "malwarebytes",
                "tunnelbear provider", "nord security", "mullvad", "proton technologies",
                "riot vanguard", "easyanticheat", "battleye", "vmware", "virtualbox",
                "oracle", "wacom", "synaptics", "elan", "logitech", "razer",
                "focusrite", "waves", "creative", "roland", "ableton",
            )
            unsigned_count = 0
            unsigned_vendor_count = 0
            for parts in rows[1:]:
                if len(parts) <= max(signed_idx, name_idx, mfg_idx):
                    continue
                is_signed = parts[signed_idx].strip().upper()
                drv_name = parts[name_idx].strip()
                mfg = parts[mfg_idx].strip()
                if is_signed in ("FALSE", "NO", ""):
                    unsigned_count += 1
                    mfg_lower = mfg.lower()
                    is_vendor_ok = any(v in mfg_lower for v in VENDOR_DRIVER_WHITELIST)
                    if is_vendor_ok:
                        # OEM vendor driver — likely legit, downgrade to LOW (info)
                        unsigned_vendor_count += 1
                        _add("LOW",
                             f"Driver 'unsigned' per driverquery (vendor OEM known): {drv_name}",
                             f"Manufacturer: {mfg} — kemungkinan false positive driverquery (banyak OEM driver pakai catalog-signed yang tidak di-detect sebagai 'IsSigned=TRUE')",
                             {"driver": drv_name, "manufacturer": mfg, "is_signed": is_signed,
                              "note": "vendor-known-ok"})
                    else:
                        _add("CRITICAL",
                             f"Driver UNSIGNED (vendor tidak dikenal): {drv_name}",
                             f"Manufacturer: {mfg} — driver tanpa Authenticode signature. Modern Windows biasanya wajib signed. Possible rootkit indicator.",
                             {"driver": drv_name, "manufacturer": mfg, "is_signed": is_signed})

            if unsigned_count == 0:
                add_finding(findings, "INFO",
                            "Semua driver signed",
                            f"{len(rows)-1} driver di-enum, semua ter-signed (Authenticode)",
                            raw=json.dumps({"total_drivers": len(rows)-1}))
    except Exception as e:
        add_finding(findings, "INFO", "Driver signature check error", str(e))

    # ── 2) Driver Path Check + BYOVD Cross-Reference ────────────────────────
    try:
        import csv as _csv
        import io as _io
        r = subprocess.run(['driverquery', '/v', '/fo', 'csv'],
                           capture_output=True, text=True, timeout=30)
        reader = _csv.reader(_io.StringIO(r.stdout))
        rows = list(reader)
        if len(rows) > 1:
            header = rows[0]
            try:
                name_idx = header.index("Module Name")
            except ValueError:
                name_idx = 0
            try:
                path_idx = header.index("Path")
            except ValueError:
                path_idx = 5
            try:
                state_idx = header.index("State")
            except ValueError:
                state_idx = 4

            byovd_hits = 0
            for parts in rows[1:]:
                if len(parts) <= max(name_idx, path_idx):
                    continue
                mod_name = parts[name_idx].strip().lower()
                drv_path = parts[path_idx].strip() if len(parts) > path_idx else ''
                state = parts[state_idx].strip() if len(parts) > state_idx else ''

                # Normalize name
                check_name = f"{mod_name}.sys" if not mod_name.endswith('.sys') else mod_name

                # 2a) BYOVD check
                for byovd_name, byovd_desc in BYOVD_DRIVERS.items():
                    if byovd_name.lower() == check_name.lower() or byovd_name.lower().split('.')[0] == mod_name:
                        byovd_hits += 1
                        _add("CRITICAL",
                             f"BYOVD driver terdeteksi: {check_name}",
                             f"Vulnerable driver — {byovd_desc} | Path: {drv_path} | State: {state}",
                             {"driver": check_name, "path": drv_path,
                              "state": state, "vulnerability": byovd_desc})
                        break

                # 2b) Path check — driver dari path non-standar
                path_lower = drv_path.lower()
                if path_lower and path_lower not in ("n/a", ""):
                    # Strip \??\ prefix (NT namespace)
                    path_clean = path_lower
                    if path_clean.startswith("\\??\\"):
                        path_clean = path_clean[4:]
                    is_standard = (path_clean.startswith("c:\\windows\\system32") or
                                   path_clean.startswith("c:\\windows\\syswow64") or
                                   path_clean.startswith("c:\\windows\\winsxs") or
                                   path_clean.startswith("\\systemroot\\system32") or
                                   # Program Files vendor drivers are legitimate location
                                   path_clean.startswith("c:\\program files\\") or
                                   path_clean.startswith("c:\\program files (x86)\\"))
                    if not is_standard:
                        is_user_writable = any(
                            path_clean.startswith(p) for p in
                            [r"c:\users\\", r"c:\temp", r"c:\programdata\temp"]
                        )
                        sev = "CRITICAL" if is_user_writable else "MEDIUM"
                        _add(sev,
                             f"Driver dari path non-standar: {check_name}",
                             f"Path: {drv_path} | State: {state} — driver loaded dari luar System32/Program Files",
                             {"driver": check_name, "path": drv_path, "state": state})
    except Exception as e:
        add_finding(findings, "INFO", "Driver path/BYOVD check error", str(e))

    # ── 3) Suspicious DLL loaded in signed-looking processes ────────────────
    # Fokus: cari DLL yang dimuat proses "legit" tapi DLL itu dari path user-writable
    SIGNED_PROCESS_NAMES = {
        "svchost.exe", "lsass.exe", "csrss.exe", "winlogon.exe", "services.exe",
        "spoolsv.exe", "explorer.exe", "dwm.exe", "taskhost.exe", "taskhostw.exe",
        "rundll32.exe", "regsvr32.exe",
    }
    USER_WRITABLE_PREFIXES = [r"c:\users\\", r"c:\temp", r"c:\programdata\temp"]
    temp_dir = os.environ.get("TEMP", "")
    if temp_dir: USER_WRITABLE_PREFIXES.append(temp_dir.lower())

    try:
        for proc in psutil.process_iter(['pid', 'name']):
            try:
                pname = (proc.info.get('name') or '').lower()
                if pname not in SIGNED_PROCESS_NAMES:
                    continue
                maps = proc.memory_maps()
                for m in maps:
                    mpath = m.path.lower()
                    if mpath.endswith('.dll'):
                        for prefix in USER_WRITABLE_PREFIXES:
                            if mpath.startswith(prefix):
                                _add("CRITICAL",
                                     f"Signed process load DLL dari user-writable path: {proc.info['name']}",
                                     f"Process: {proc.info['name']} (PID {proc.info['pid']}) | DLL: {m.path} — indikator DLL side-loading / sideload injection",
                                     {"process": proc.info['name'], "pid": proc.info['pid'],
                                      "dll_path": m.path})
                                break
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
    except Exception as e:
        add_finding(findings, "INFO", "DLL in signed process check error", str(e))

    return findings, sig_list


