def check_lolbas_abuse():
    """Deteksi penyalahgunaan LOLBin di running process, scheduled task, dan prefetch."""
    findings = []
    lolbas_list = []
    import re as _re

    def _add(sev, title, detail, data):
        entry = {"check": title, "detail": detail, "data": data, "severity": sev}
        lolbas_list.append(entry)
        add_finding(findings, sev, title, detail,
                    raw=json.dumps(entry, ensure_ascii=False, default=str))

    # ── 1) Scan running processes ───────────────────────────────────────────
    try:
        for proc in psutil.process_iter(['pid', 'name', 'exe', 'cmdline']):
            try:
                name = (proc.info.get('name') or '').lower()
                cmdline = " ".join(proc.info.get('cmdline') or [])
                if not cmdline:
                    continue
                for bin_rx, pattern_rx, sev, desc in LOLBAS_PATTERNS:
                    if _re.search(bin_rx, name, _re.I):
                        if _re.search(pattern_rx, cmdline):
                            _add(sev,
                                 f"LOLBAS abuse: {name} dengan pattern mencurigakan",
                                 f"{desc} | CMD: {cmdline[:200]} | PID: {proc.info['pid']}",
                                 {"binary": name, "pid": proc.info['pid'],
                                  "cmdline": cmdline, "pattern_desc": desc})
                            break
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
    except Exception as e:
        add_finding(findings, "INFO", "LOLBAS process scan error", str(e))

    # ── 2) Scan scheduled tasks XML untuk LOLBin patterns ───────────────────
    try:
        import csv as _csv, io as _io
        r = subprocess.run(['schtasks', '/query', '/fo', 'CSV', '/v'],
                           capture_output=True, text=True, timeout=30)
        reader = _csv.reader(_io.StringIO(r.stdout))
        rows = list(reader)
        if len(rows) > 1:
            header = rows[0]
            try:
                cmd_idx = header.index("Task To Run")
                name_idx = header.index("TaskName")
            except ValueError:
                cmd_idx, name_idx = 8, 0
            for parts in rows[1:]:
                if len(parts) <= max(cmd_idx, name_idx):
                    continue
                task_name = parts[name_idx]
                task_cmd = parts[cmd_idx]
                # Skip built-in Microsoft scheduled tasks — they're legit
                # (contoh: \Microsoft\Windows\Application Experience\SdbinstMergeDbTask)
                if task_name.lower().startswith(("\\microsoft\\", "\\windows\\")):
                    continue
                for bin_rx, pattern_rx, sev, desc in LOLBAS_PATTERNS:
                    if _re.search(bin_rx, task_cmd, _re.I):
                        if _re.search(pattern_rx, task_cmd, _re.I):
                            _add(sev,
                                 f"LOLBAS abuse di Scheduled Task: {task_name}",
                                 f"{desc} | Task: {task_name} | CMD: {task_cmd[:200]}",
                                 {"task_name": task_name, "command": task_cmd,
                                  "pattern_desc": desc})
                            break
    except Exception as e:
        add_finding(findings, "INFO", "LOLBAS schtasks scan error", str(e))

    # ── 3) Scan registry Run keys for LOLBin patterns ───────────────────────
    run_keys = [
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"),
        (winreg.HKEY_CURRENT_USER,  r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_CURRENT_USER,  r"SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"),
    ]
    for hive, path in run_keys:
        try:
            k = winreg.OpenKey(hive, path)
            i = 0
            while True:
                try:
                    name, val, _ = winreg.EnumValue(k, i); i += 1
                    if not isinstance(val, str):
                        continue
                    for bin_rx, pattern_rx, sev, desc in LOLBAS_PATTERNS:
                        if _re.search(bin_rx, val, _re.I) and _re.search(pattern_rx, val, _re.I):
                            _add(sev,
                                 f"LOLBAS abuse di Run key: {name}",
                                 f"{desc} | Registry: HKEY\\{path}\\{name} | Value: {val[:200]}",
                                 {"registry_path": path, "value_name": name,
                                  "value": val, "pattern_desc": desc})
                            break
                except OSError:
                    break
            winreg.CloseKey(k)
        except Exception:
            continue

    return findings, lolbas_list


# ── MODULE 26 [HMD-08]: LIVING-OFF-THE-LAND PERSISTENCE ──────────────────────
def check_lotl_persistence():
    """Deteksi Living-off-the-Land persistence: Defender tamper, Office trust, service hijack."""
    findings = []
    lotl_list = []

    def _reg_read(hive, path, name):
        try:
            k = winreg.OpenKey(hive, path)
            val, _ = winreg.QueryValueEx(k, name)
            winreg.CloseKey(k)
            return val
        except Exception:
            return None

    def _add(sev, title, detail, data):
        entry = {"check": title, "detail": detail, "data": data, "severity": sev}
        lotl_list.append(entry)
        add_finding(findings, sev, title, detail,
                    raw=json.dumps(entry, ensure_ascii=False, default=str))

    # ── 1) Defender Tamper Indicators ───────────────────────────────────────
    defender_tamper_checks = [
        (r"SOFTWARE\Policies\Microsoft\Windows Defender", "DisableAntiSpyware", 1,
         "CRITICAL", "Windows Defender MATI SELURUHNYA via policy"),
        (r"SOFTWARE\Microsoft\Windows Defender", "DisableAntiSpyware", 1,
         "CRITICAL", "Windows Defender MATI SELURUHNYA (lokal)"),
        (r"SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection",
         "DisableRealtimeMonitoring", 1,
         "CRITICAL", "Defender Real-time Protection DISABLED (policy)"),
        (r"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
         "DisableBehaviorMonitoring", 1,
         "HIGH", "Defender Behavior Monitoring DISABLED"),
        (r"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
         "DisableOnAccessProtection", 1,
         "HIGH", "Defender On-Access Protection DISABLED"),
        (r"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
         "DisableScanOnRealtimeEnable", 1,
         "HIGH", "Defender Scan-on-Realtime-Enable DISABLED"),
        (r"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection",
         "DisableIOAVProtection", 1,
         "HIGH", "Defender IOAV (download) protection DISABLED"),
        (r"SOFTWARE\Policies\Microsoft\Windows Defender\Spynet",
         "SubmitSamplesConsent", 2,
         "MEDIUM", "Defender sample submission disabled (bisa jadi info kalau air-gap)"),
        (r"SOFTWARE\Microsoft\Windows Defender\SpyNet",
         "SpynetReporting", 0,
         "MEDIUM", "Defender SpyNet reporting disabled"),
    ]

    for path, name, trigger_val, sev, desc in defender_tamper_checks:
        v = _reg_read(winreg.HKEY_LOCAL_MACHINE, path, name)
        if v == trigger_val:
            _add(sev, f"Defender tamper: {name}",
                 f"{desc} — Registry: HKLM\\{path}\\{name} = {v}",
                 {"check": "defender_tamper", "registry": path,
                  "value_name": name, "actual": v, "trigger": trigger_val})

    # ── 2) WDigest plaintext credential enabled (post-exploit indicator) ────
    v = _reg_read(winreg.HKEY_LOCAL_MACHINE,
                  r"SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest",
                  "UseLogonCredential")
    if v == 1:
        _add("CRITICAL", "WDigest plaintext DI-ENABLE (kemungkinan post-serangan)",
             "UseLogonCredential=1 — attacker aktifkan untuk credential dump via Mimikatz | Registry: HKLM\\SYSTEM\\...\\WDigest\\UseLogonCredential",
             {"registry": "HKLM\\SYSTEM\\CurrentControlSet\\Control\\SecurityProviders\\WDigest",
              "value_name": "UseLogonCredential", "value": v})

    # ── 3) Office Trust Center Bypass ───────────────────────────────────────
    office_apps = ["Word", "Excel", "PowerPoint", "Outlook", "Access"]
    office_versions = ["16.0", "15.0", "14.0"]

    for ver in office_versions:
        for app in office_apps:
            # VBA Warnings = 1 means "Enable all macros" (dangerous)
            vba = _reg_read(winreg.HKEY_CURRENT_USER,
                            f"Software\\Microsoft\\Office\\{ver}\\{app}\\Security",
                            "VBAWarnings")
            if vba == 1:
                _add("CRITICAL",
                     f"Office {app} {ver}: ALL MACROS ENABLED",
                     f"VBAWarnings=1 — semua macro di-enable tanpa warning. Ultra-dangerous — classic Office macro malware vector. | Registry: HKCU\\Software\\Microsoft\\Office\\{ver}\\{app}\\Security\\VBAWarnings",
                     {"app": app, "version": ver,
                      "registry_value": "VBAWarnings", "value": vba})
            # DisableAttachmentsInPV — attachments bypass Protected View
            disable_pv = _reg_read(winreg.HKEY_CURRENT_USER,
                                   f"Software\\Microsoft\\Office\\{ver}\\{app}\\Security",
                                   "DisableAttachmentsInPV")
            if disable_pv == 1:
                _add("HIGH",
                     f"Office {app} {ver}: Protected View DISABLED untuk attachments",
                     f"DisableAttachmentsInPV=1 — attachment buka langsung tanpa sandbox. | Registry: HKCU\\...\\Office\\{ver}\\{app}\\Security",
                     {"app": app, "version": ver, "registry_value": "DisableAttachmentsInPV"})
            # DisableInternetFilesInPV
            disable_ipv = _reg_read(winreg.HKEY_CURRENT_USER,
                                    f"Software\\Microsoft\\Office\\{ver}\\{app}\\Security",
                                    "DisableInternetFilesInPV")
            if disable_ipv == 1:
                _add("HIGH",
                     f"Office {app} {ver}: Protected View DISABLED untuk internet files",
                     f"DisableInternetFilesInPV=1 — file dari internet buka tanpa PV",
                     {"app": app, "version": ver})

    # ── 4) Service DLL Hijack Check ─────────────────────────────────────────
    # Service berbasis svchost memakai ServiceDLL di HKLM\SYSTEM\...\Services\<svc>\Parameters\ServiceDLL
    # Flag kalau ServiceDLL dari path non-System32
    try:
        services_path = r"SYSTEM\CurrentControlSet\Services"
        k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, services_path)
        i = 0
        svc_dll_count = 0
        while True:
            try:
                svc = winreg.EnumKey(k, i); i += 1
                param_path = f"{services_path}\\{svc}\\Parameters"
                try:
                    sk = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, param_path)
                    try:
                        svc_dll, _ = winreg.QueryValueEx(sk, "ServiceDll")
                        if not svc_dll:
                            raise ValueError("empty")
                        # Expand %windir%, %systemroot%, %programfiles%, dll
                        svc_dll_expanded = os.path.expandvars(svc_dll).lower()
                        # ServiceDll dari path non-standar
                        is_standard = (svc_dll_expanded.startswith(r"c:\windows\system32") or
                                       svc_dll_expanded.startswith(r"c:\windows\syswow64") or
                                       svc_dll_expanded.startswith(r"c:\windows\servicing") or
                                       svc_dll_expanded.startswith(r"c:\program files\windows defender") or
                                       svc_dll_expanded.startswith(r"c:\program files (x86)\windows defender"))
                        if not is_standard:
                            # Juga toleransi untuk vendor OEM legit di Program Files
                            vendor_ok = any(
                                svc_dll_expanded.startswith(f"c:\\program files\\{v}") or
                                svc_dll_expanded.startswith(f"c:\\program files (x86)\\{v}")
                                for v in ("microsoft", "windows defender", "common files\\microsoft"))
                            if not vendor_ok:
                                _add("HIGH",
                                     f"Service DLL dari path NON-STANDARD: {svc}",
                                     f"ServiceDll: {svc_dll} (resolved: {svc_dll_expanded}) — service svchost biasanya load DLL dari System32 | Service: {svc}",
                                     {"service": svc, "service_dll": svc_dll,
                                      "resolved": svc_dll_expanded, "registry": param_path})
                                svc_dll_count += 1
                    except Exception:
                        pass
                    winreg.CloseKey(sk)
                except Exception:
                    pass
            except OSError:
                break
        winreg.CloseKey(k)
    except Exception as e:
        add_finding(findings, "INFO", "Service DLL enum error", str(e))

    # ── 5) DisablePasswordChange / DisableDomainCreds / NoLMHash ────────────
    checks_misc = [
        (r"SYSTEM\CurrentControlSet\Control\Lsa", "DisableDomainCreds", 1,
         "MEDIUM", "DisableDomainCreds=1 — domain credentials not cached (bisa legit atau bypass)"),
        (r"SYSTEM\CurrentControlSet\Services\Netlogon\Parameters",
         "RequireSignOrSeal", 0,
         "HIGH", "Netlogon RequireSignOrSeal=0 — rentan Zerologon"),
    ]
    for path, name, trigger, sev, desc in checks_misc:
        v = _reg_read(winreg.HKEY_LOCAL_MACHINE, path, name)
        if v == trigger:
            _add(sev, f"LotL misconfig: {name}",
                 f"{desc} — Registry: HKLM\\{path}\\{name} = {v}",
                 {"registry": path, "value_name": name, "value": v})

    # ── 6) Defender Scan Exclusion Count Anomaly ────────────────────────────
    excl_paths = [r"SOFTWARE\Microsoft\Windows Defender\Exclusions\Paths",
                  r"SOFTWARE\Microsoft\Windows Defender\Exclusions\Processes",
                  r"SOFTWARE\Microsoft\Windows Defender\Exclusions\Extensions"]
    total_excl = 0
    for ep in excl_paths:
        try:
            k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, ep)
            i = 0
            while True:
                try:
                    winreg.EnumValue(k, i); i += 1
                except OSError:
                    break
            total_excl += i
            winreg.CloseKey(k)
        except Exception:
            pass
    if total_excl > 20:
        _add("MEDIUM",
             f"Defender exclusion count anomali: {total_excl} entries",
             f"Jumlah exclusion yang banyak ({total_excl}) — periksa manual, kemungkinan attacker tambah exclusion",
             {"total_exclusions": total_excl})

    return findings, lotl_list


